import React from 'react';
import './About.css';

function About() {
  return (
    <div className="about-container">
      <h1>About Us</h1>
      <p>
        Welcome to our camera self-studio! We are dedicated to providing a creative space for photography enthusiasts and professionals alike. Our mission is to empower individuals to capture their unique moments in a stylish and comfortable environment.
      </p>
      <p>
        Our team consists of experienced photographers and creative minds who are passionate about helping you achieve your vision. Whether you're looking to take stunning portraits, product photography, or simply have fun with friends, our studio is equipped to meet your needs.
      </p>
      <p>
        Join us in exploring the art of photography and let us help you create lasting memories!
      </p>
    </div>
  );
}

export default About;
